CREATE OR REPLACE VIEW CORE.DIM_LOCATION (
    LOCATION_SK COMMENT 'Surrogate key (hash of natural key)',
    LOCATION_ID COMMENT 'Identifier ''location id''. Origin: FM Business Layer.Location.LocationID',
    CITY COMMENT 'Attribute ''city''. Origin: FM Business Layer.Location.City',
    CLIMATE_ZONE COMMENT 'Attribute ''climate zone''. Origin: FM Business Layer.Location.ClimateZone',
    POSTAL_CODE COMMENT 'Attribute ''postal code''. Origin: inferred from report usage (Energy_Billing_Package)',
    REGION COMMENT 'Attribute ''region''. Origin: FM Business Layer.Location.Region',
    STATE_PROVINCE COMMENT 'Attribute ''state province''. Origin: FM Business Layer.Location.StateProvince'
)
  WITH ROW ACCESS POLICY SEC.RAP_REGION ON (REGION)
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'ENTERPRISE', GOV.RETENTION = '7 years (FERC)')
  COMMENT = 'Dimension at Location grain. Source: ENERGY_DW.LOCATION. Origin: FM Business Layer.Location (conformed across Energy_Billing_Package, Energy_Operations_Package)'
AS
SELECT
    HASH(src.LOCATION_ID)                         AS LOCATION_SK,
    src.LOCATION_ID                               AS LOCATION_ID,
    src.CITY                                      AS CITY,
    src.CLIMATE_ZONE                              AS CLIMATE_ZONE,
    src.POSTAL_CODE                               AS POSTAL_CODE,
    src.REGION                                    AS REGION,
    src.STATE_PROVINCE                            AS STATE_PROVINCE
FROM RAW_ENERGY_DW.LOCATION src;
